  "Dockerfile": "# Builds the app into a small image. Irreplaceable state lives in the /data volume.\nFROM node:24-slim AS build\nWORKDIR /app\nRUN corepack enable\nCOPY package.json pnpm-lock.yaml pnpm-workspace.yaml ./\nRUN pnpm install --frozen-lockfile\nCOPY . .\nRUN pnpm build && pnpm prune --prod\n\nFROM node:24-slim\nWORKDIR /app\nENV NODE_ENV=production PORT=3000 DATA_DIR=/data\nCOPY --from=build /app/package.json ./\nCOPY --from=build /app/node_modules ./node_modules\nCOPY --from=build /app/dist ./dist\nCOPY --from=build /app/drizzle ./drizzle\nVOLUME /data\nEXPOSE 3000\nHEALTHCHECK CMD node -e \"fetch('http://localhost:' + process.env.PORT + '/health').then((r) => process.exit(r.ok ? 0 : 1), () => process.exit(1))\"\nCMD [\"node_modules/.bin/srvx\", \"--prod\", \"-s\", \"../client\", \"dist/server/server.js\"]\n",
  "drizzle.config.ts": "import { defineConfig } from \"drizzle-kit\";\n\nexport default defineConfig({\n  dialect: \"sqlite\",\n  schema: \"./src/db/schema.ts\",\n  out: \"./drizzle\",\n  casing: \"snake_case\",\n  dbCredentials: { url: `${process.env.DATA_DIR ?? \"data\"}/db/app.db` },\n});\n",
